import { withForm } from "@/hooks/formContext";
import { PlusIcon, TrashIcon, ChevronDownIcon } from "@radix-ui/react-icons";
import { Collapsible } from "radix-ui";
import "../../../style/table.css";
import "../select.css";
import {
  defaultFormValues,
  StorageSchema,
  TemplateOptions,
  VendorOptions,
} from "@/components/form/shared";
import * as z from "zod";
import { useState } from "react";

interface Option {
  options: Record<string, string>;
  inactiveOptions?: Record<string, string>;
  inactiveText?: string;
  groups?: Record<string, number>;
  multiple?: boolean;
  emptyOpt?: string;
}

const defaultb2drop: z.input<typeof StorageSchema> = {
  template: "b2drop",
  relativemountpath: "",
  readonly: false,
  path: "",
  user: "",
  obscure_pass: "",
};

export const StorageForm = withForm({
  defaultValues: defaultFormValues,
  render: function Render({ form }) {
    const [templateOptions, setTemplateOptions] = useState<Option>({
      options: {},
    });
    const [vendorOptions, setVendorOptions] = useState<Option>({
      options: {},
    });
    const handleAdd = () => {
      form.pushFieldValue("storage.mounts", defaultb2drop);
    };

    return (
      <div className="env-variables-entry">
        <div className="env-variables-entry__header">
          <span className="env-variables-entry__header-text">
            Add Storage Mount
          </span>
          <button
            type="button"
            className="env-variables-entry__add-btn"
            aria-label="Add environment variable"
            onClick={handleAdd}
          >
            <PlusIcon />
          </button>
        </div>

        <form.AppField name="storage.mounts" mode="array">
          {(field) => {
            return (
              <>
                {field.state.value.length > 0 && (
                  <table className="jh-table env-variables-entry__table">
                    <thead className="jh-thead">
                      <tr>
                        <th></th>
                        <th>Template</th>
                        <th>Action</th>
                      </tr>
                    </thead>
                    {field.state.value.map((mount, i) => {
                      const templateLabel =
                        TemplateOptions.find(
                          (option) => option.value === mount.template,
                        )?.label ??
                        mount.template ??
                        "Template Value";

                      return (
                        <Collapsible.Root key={i} asChild>
                          <tbody className="jh-table__body">
                            <Collapsible.Trigger asChild>
                              <tr className="jh-row">
                                <td
                                  style={{ width: "2rem", textAlign: "center" }}
                                >
                                  <ChevronDownIcon className="storage-mount-chevron" />
                                </td>
                                <td>{templateLabel}</td>
                                <td style={{ textAlign: "center" }}>
                                  <button
                                    type="button"
                                    className="env-variables-entry__remove-btn"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      field.removeValue(i);
                                    }}
                                    aria-label="Remove storage mount"
                                  >
                                    <TrashIcon />
                                  </button>
                                </td>
                              </tr>
                            </Collapsible.Trigger>
                            <Collapsible.Content asChild>
                              <tr>
                                <td colSpan={3} className="jh-content-cell">
                                  <div className="env-variables-entry__content">
                                    <form.AppField
                                      key={i}
                                      name={`storage.mounts[${i}].template`}
                                      listeners={{
                                        onMount: () => {
                                          setTemplateOptions({
                                            options: Object.fromEntries(
                                              TemplateOptions.map((r) => [
                                                r.value,
                                                r.label,
                                              ]),
                                            ),
                                          });
                                        },
                                      }}
                                    >
                                      {(subfield) => (
                                        <subfield.select
                                          label="Template"
                                          options={templateOptions}
                                        />
                                      )}
                                    </form.AppField>
                                    <form.Subscribe
                                      selector={(state) =>
                                        state.values.storage.mounts?.[i]
                                          .template
                                      }
                                    >
                                      {(template) => (
                                        <>
                                          {template === "b2drop" && (
                                            <>
                                              <form.AppField
                                                name={`storage.mounts[${i}].relativemountpath`}
                                                listeners={{
                                                  onMount: ({ fieldApi }) => {
                                                    fieldApi.form.setFieldValue(
                                                      `storage.mounts[${i}].relativemountpath`,
                                                      template,
                                                    );
                                                  },
                                                }}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Relative Mount Path" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].readonly`}
                                              >
                                                {(subfield) => (
                                                  <subfield.checkbox label="Read Only" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].path`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Path" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].user`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Username" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].obscure_pass`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text
                                                    label="Password"
                                                    secret
                                                  />
                                                )}
                                              </form.AppField>
                                            </>
                                          )}
                                          {template === "aws" && (
                                            <>
                                              <form.AppField
                                                name={`storage.mounts[${i}].relativemountpath`}
                                                listeners={{
                                                  onMount: ({ fieldApi }) => {
                                                    fieldApi.form.setFieldValue(
                                                      `storage.mounts[${i}].relativemountpath`,
                                                      template,
                                                    );
                                                  },
                                                }}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Relative Mount Path" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].readonly`}
                                              >
                                                {(subfield) => (
                                                  <subfield.checkbox label="Read Only" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].remotepath`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Bucket Name" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].region`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Region" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].access_key_id`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Username" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].secret_access_key`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text
                                                    label="Password"
                                                    secret
                                                  />
                                                )}
                                              </form.AppField>
                                            </>
                                          )}
                                          {template === "s3" && (
                                            <>
                                              <form.AppField
                                                name={`storage.mounts[${i}].relativemountpath`}
                                                listeners={{
                                                  onMount: ({ fieldApi }) => {
                                                    fieldApi.form.setFieldValue(
                                                      `storage.mounts[${i}].relativemountpath`,
                                                      template,
                                                    );
                                                  },
                                                }}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Relative Mount Path" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].readonly`}
                                              >
                                                {(subfield) => (
                                                  <subfield.checkbox label="Read Only" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].provider`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Provider" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].remotepath`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Bucket Name" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].endpoint`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Endpoint" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].access_key_id`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Username" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].secret_access_key`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text
                                                    label="Password"
                                                    secret
                                                  />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].region`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Region" />
                                                )}
                                              </form.AppField>
                                            </>
                                          )}
                                          {template === "webdav" && (
                                            <>
                                              <form.AppField
                                                name={`storage.mounts[${i}].relativemountpath`}
                                                listeners={{
                                                  onMount: ({ fieldApi }) => {
                                                    fieldApi.form.setFieldValue(
                                                      `storage.mounts[${i}].relativemountpath`,
                                                      template,
                                                    );
                                                  },
                                                }}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Relative Mount Path" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].readonly`}
                                              >
                                                {(subfield) => (
                                                  <subfield.checkbox label="Read Only" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].path`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Path" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].url`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="URL" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].vendor`}
                                                listeners={{
                                                  onMount: () => {
                                                    setVendorOptions({
                                                      options:
                                                        Object.fromEntries(
                                                          VendorOptions.map(
                                                            (r) => [
                                                              r.value,
                                                              r.label,
                                                            ],
                                                          ),
                                                        ),
                                                    });
                                                  },
                                                }}
                                              >
                                                {(subfield) => (
                                                  <subfield.select
                                                    label="Vendor"
                                                    options={vendorOptions}
                                                  />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].user`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Username" />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].obscure_pass`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text
                                                    label="Password"
                                                    secret
                                                  />
                                                )}
                                              </form.AppField>
                                              <form.AppField
                                                name={`storage.mounts[${i}].bearer_token`}
                                              >
                                                {(subfield) => (
                                                  <subfield.text label="Bearer Token" />
                                                )}
                                              </form.AppField>
                                            </>
                                          )}
                                        </>
                                      )}
                                    </form.Subscribe>
                                  </div>
                                </td>
                              </tr>
                            </Collapsible.Content>
                          </tbody>
                        </Collapsible.Root>
                      );
                    })}
                  </table>
                )}
              </>
            );
          }}
        </form.AppField>
      </div>
    );
  },
});
