import { useState } from "react";
import {
  homeTriggerOption,
  homeTriggerSystem,
  homeTriggerFlavor,
} from "../dataFunctions";
import { withForm } from "@/hooks/formContext";
import { HPCForm } from "./HPCForm";
import { Repo2DockerForm } from "./Repo2DockerForm";
import { CustomDockerForm } from "./CustomDockerForm";
import FlavorInfo from "../../FlavorInfo/FlavorInfo";
import FlavorLegend from "../../FlavorLegend/FlavorLegend";
import {
  getBackendServices,
  getSystemConfig,
} from "@/utils/frontendCollectionHelper";
import { defaultFormValues } from "../shared";

interface Option {
  options: Record<string, string>;
  inactiveOptions?: Record<string, string>;
  inactiveText?: string;
  groups?: Record<string, number>;
  multiple?: boolean;
  emptyOpt?: string;
}

export const HomeForm = withForm({
  defaultValues: defaultFormValues,
  props: {
    configId: "",
    userOptions: undefined,
    configOptions: undefined,
  },
  render: function Render({ form, configId }) {
    const [optionOptions] = useState<Option>(homeTriggerOption());
    const [systemOptions, setSystemOptions] = useState<Option>(
      homeTriggerSystem(form.state.values.option, configId, "jupyterlab"),
    );
    const [flavorOptions, setFlavorOptions] = useState<Option>(
      homeTriggerFlavor(form.state.values.system),
    );

    const getSystemType = (system: string) => {
      const systemConfig = getSystemConfig();
      const backendServicesConfig = getBackendServices();
      const backendService = systemConfig[system].backendService;
      const ret = backendServicesConfig[backendService]?.mapping ?? system;
      console.log("getSystemType result: ", ret);
      return ret;
    };

    return (
      <>
        <form.AppField name="name">
          {(field) => (
            <>
              <field.text label="Name" />
              {field.state.meta.errors?.length > 0 && (
                <span className="entry__error">
                  {field.state.meta.errors
                    .map((err) => err.message ?? err)
                    .join(", ")}
                </span>
              )}
            </>
          )}
        </form.AppField>
        <form.AppField name="option">
          {(field) => <field.select label="Option" options={optionOptions} />}
        </form.AppField>
        <form.AppField
          name="system"
          validators={{
            onChangeListenTo: ["option"],
            onChange: ({ value, fieldApi }) => {
              const option = fieldApi.form.getFieldValue("option");
              const options = homeTriggerSystem(option, configId, "jupyterlab");
              if (options.inactiveOptions && options.inactiveOptions[value]) {
                console.warn(
                  `Selected value "${value}" is in inactive options. Resetting selection.`,
                );
                const firstOption = Object.keys(options.options)[0];
                if (firstOption) {
                  fieldApi.handleChange(firstOption);
                }
              }
              setSystemOptions(options ?? []);
            },
          }}
        >
          {(field) => <field.select label="System" options={systemOptions} />}
        </form.AppField>
        <hr />
        <form.Subscribe selector={(state) => state.values.system}>
          {(system) => (
            <>
              {getSystemType(system) === "unicore" && (
                <>
                  <HPCForm form={form} configId={configId} />
                </>
              )}
            </>
          )}
        </form.Subscribe>
        <form.Subscribe selector={(state) => state.values.option}>
          {(option) => (
            <>
              {option === "custom" && (
                <>
                  <CustomDockerForm form={form} />
                </>
              )}
            </>
          )}
        </form.Subscribe>
        <form.Subscribe selector={(state) => state.values.option}>
          {(option) => (
            <>
              {option === "repo2docker" && (
                <>
                  <Repo2DockerForm form={form} />
                </>
              )}
            </>
          )}
        </form.Subscribe>
        <form.Subscribe selector={(state) => state.values.system}>
          {(system) => (
            <>
              {getSystemType(system) !== "unicore" && (
                <>
                  <form.AppField
                    name="flavor"
                    validators={{
                      onChangeListenTo: ["system"], // homeTriggerFlavor
                      onChange: ({ value, fieldApi }) => {
                        const system = fieldApi.form.getFieldValue("system");
                        const options = homeTriggerFlavor(system);
                        console.log(
                          "homeTriggerFlavor onChange result: ",
                          options,
                        );
                        console.log("Selected flavor: ", value);
                        if (
                          value == "" &&
                          options.options &&
                          Object.keys(options.options).length > 0
                        ) {
                          const firstOption = Object.keys(options.options)[0];
                          fieldApi.handleChange(firstOption);
                        }
                        setFlavorOptions(options ?? []);
                      },
                    }}
                    listeners={{
                      onMount: ({ value, fieldApi }) => {
                        const system = fieldApi.form.getFieldValue("system");
                        const options = homeTriggerFlavor(system);
                        console.log(
                          "homeTriggerFlavor onMount result: ",
                          options,
                        );
                        setFlavorOptions(options ?? []);
                        if (
                          value == "" &&
                          options.options &&
                          Object.keys(options.options).length > 0
                        ) {
                          const firstOption = Object.keys(options.options)[0];
                          fieldApi.handleChange(firstOption);
                        }
                      },
                    }}
                  >
                    {(field) => (
                      <field.select label="Flavor" options={flavorOptions} />
                    )}
                  </form.AppField>
                  <FlavorLegend />
                  <FlavorInfo system={system} flavors={undefined} />
                </>
              )}
            </>
          )}
        </form.Subscribe>
      </>
    );
  },
});
