import React from "react";
import { Tabs } from "radix-ui";
import { getFrontendConfig } from "@/utils/frontendConfigHelper";
import { HomeForm } from "./form/subforms/HomeForm";
import { EnvVariablesForm } from "./form/subforms/EnvVariablesForm";
import { ResourcesForm } from "./form/subforms/ResourceForm";
import { StorageForm } from "./form/subforms/StorageForm";
import { ModuleForm } from "./form/subforms/ModuleForm";
import Logger from "@/components/Logger/Logger";
import { kubeSystems } from "@/utils/kubeHelper";
import { getPartitionAndInteractivePartition } from "@/utils/unicoreHelper";
import { useStore } from "@tanstack/react-form";
import { fillMappingDict } from "@/utils/sharedHelper";
const mappingdict = fillMappingDict();

interface JupyterLabTabProps {
  form: any;
  configId: string;
  activeTab: string;
  onTabChange: (tab: string) => void;
}

const JupyterLabTab = ({
  form,
  configId,
  activeTab,
  onTabChange,
}: JupyterLabTabProps) => {
  console.log("JupyterLabTab component called with configId:", configId);
  const system = useStore(form.store, (state) => state.values.system);
  const option = useStore(form.store, (state) => state.values.option);
  const partition = useStore(form.store, (state) => state.values.hpc.partition);
  const account = useStore(form.store, (state) => state.values.hpc.account);
  const project = useStore(form.store, (state) => state.values.hpc.project);
  const frontendConfig = getFrontendConfig();
  const tabs =
    frontendConfig.services.options[frontendConfig.services.default].navbar;
  const [partitions, interactivePartition] =
    getPartitionAndInteractivePartition(system, account, project);
  const isInteractivePartition = (partition: string) => {
    if (partitions && Array.isArray(partitions)) {
      const interactivePartitions = partitions.slice(
        interactivePartition as number,
      );
      return interactivePartitions.some((p) => p.includes(partition));
    } else return false;
  };
  return (
    <Tabs.Root
      value={activeTab}
      onValueChange={onTabChange}
      className="jupyter-lab-tabs"
    >
      <Tabs.List className="jupyter-lab-tabs__list">
        <Tabs.Trigger
          key="labconfig"
          value="labconfig"
          className="jupyter-lab-tabs__trigger"
        >
          Lab Config
        </Tabs.Trigger>
        {kubeSystems.includes(system) && (
          <Tabs.Trigger
            key="storage"
            value="storage"
            className="jupyter-lab-tabs__trigger"
          >
            Storage
          </Tabs.Trigger>
        )}
        <Tabs.Trigger
          key="envvariables"
          value="envvariables"
          className="jupyter-lab-tabs__trigger"
        >
          Environment Variables
        </Tabs.Trigger>
        {isInteractivePartition(partition) && (
          <Tabs.Trigger
            key="resources"
            value="resources"
            className="jupyter-lab-tabs__trigger"
          >
            Resources
          </Tabs.Trigger>
        )}
        {mappingdict["jupyterlab"].option[option] == "lmod" && (
          <Tabs.Trigger
            key="modules"
            value="modules"
            className="jupyter-lab-tabs__trigger"
          >
            Kernels and Extensions
          </Tabs.Trigger>
        )}
        {configId && (
          <Tabs.Trigger
            key="logs"
            value="logs"
            className="jupyter-lab-tabs__trigger"
          >
            Logs
          </Tabs.Trigger>
        )}
      </Tabs.List>

      <form
        key={configId}
        style={{ width: "100%" }}
        onSubmit={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
      >
        {Object.entries(tabs).map(([tabKey, _tabConfig]) => (
          <Tabs.Content
            key={tabKey}
            value={tabKey}
            className="jupyter-lab-tabs__content"
          >
            {tabKey === "labconfig" && <HomeForm form={form} />}
            {tabKey === "envvariables" && <EnvVariablesForm form={form} />}
            {tabKey === "resources" && <ResourcesForm form={form} />}
            {tabKey === "storage" && <StorageForm form={form} />}
            {tabKey === "modules" && <ModuleForm form={form} />}
            {tabKey === "logs" && <Logger configID={configId as string} />}

            <div className="jupyter-lab-tabs__actions">
              <div className="jupyter-lab-tabs__actions-left">
                {configId && (
                  <>
                    <form.AppForm>
                      <form.share label="Share" configId={configId} />
                    </form.AppForm>
                    <form.AppForm>
                      <form.rtc label="RTC" configId={configId} />
                    </form.AppForm>
                    <form.AppForm>
                      <form.url />
                    </form.AppForm>
                    <form.AppForm>
                      <form.save label="Save" configId={configId} />
                    </form.AppForm>
                    <form.AppForm>
                      <form.resetButton />
                    </form.AppForm>
                    <form.AppForm>
                      <form.delete label="Delete" configId={configId} />
                    </form.AppForm>
                  </>
                )}
              </div>
              {!configId && (
                <form.AppForm>
                  <form.startNew />
                </form.AppForm>
              )}
            </div>
          </Tabs.Content>
        ))}
      </form>
    </Tabs.Root>
  );
};

export default JupyterLabTab;
