import { useEffect, useState } from "react";
import { AlertDialog } from "radix-ui";
import "./LogoutDialog.css";

const LogoutDialog = () => {
  const [open, setOpen] = useState(false);
  const [stopJupyterLabs, setStopJupyterLabs] = useState(true);
  const [logoutAllDevices, setLogoutAllDevices] = useState(true);

  useEffect(() => {
    const handler = () => setOpen(true);
    window.addEventListener("open-logout-dialog", handler);
    return () => window.removeEventListener("open-logout-dialog", handler);
  }, []);

  const handleLogout = () => {
    console.log("Logging out...", { stopJupyterLabs, logoutAllDevices });
    setOpen(false);
  };

  return (
    <AlertDialog.Root open={open} onOpenChange={setOpen}>
      <AlertDialog.Portal>
        <AlertDialog.Overlay className="logout-overlay" />
        <AlertDialog.Content className="logout-content">
          <AlertDialog.Title className="logout-title">Logout</AlertDialog.Title>

          <AlertDialog.Description className="logout-description">
            Jupyter-JSC Logout.
          </AlertDialog.Description>

          <div className="logout-checkboxes">
            <label className="logout-checkbox-label">
              <input
                type="checkbox"
                checked={stopJupyterLabs}
                onChange={(e) => setStopJupyterLabs(e.target.checked)}
              />
              Stop all running JupyterLabs.
            </label>
            <label className="logout-checkbox-label">
              <input
                type="checkbox"
                checked={logoutAllDevices}
                onChange={(e) => setLogoutAllDevices(e.target.checked)}
              />
              Logout from all devices.
            </label>
          </div>

          <div className="logout-actions">
            <AlertDialog.Action asChild>
              <button className="logout-btn-confirm" onClick={handleLogout}>
                LOGOUT
              </button>
            </AlertDialog.Action>
            <AlertDialog.Cancel asChild>
              <button className="logout-btn-cancel">CANCEL</button>
            </AlertDialog.Cancel>
          </div>
        </AlertDialog.Content>
      </AlertDialog.Portal>
    </AlertDialog.Root>
  );
};

export default LogoutDialog;
