import { InfoCircledIcon } from "@radix-ui/react-icons";
import { Progress } from "radix-ui";
import "./FlavorInfo.css";

interface FlavorDescription {
  display_name: string;
  description: string;
  current?: number;
  max: number;
  weight?: number;
}

interface FlavorBarProps {
  description: FlavorDescription;
}

const FlavorBar = ({ description }: FlavorBarProps) => {
  const current = description.current ?? 2;
  const maxAllowed = description.max;
  // Flavor not valid, skip rendering
  if (
    maxAllowed === 0 ||
    current < 0 ||
    maxAllowed == null ||
    current == null
  ) {
    return null;
  }

  let usedVariant: "primary" | "danger" = "primary";
  let progressTooltip: string;
  let remainingLabel: number | string;
  let currentWidth: number;
  let remainingWidth: number;

  if (maxAllowed === -1) {
    // Infinite allowed
    progressTooltip = `${current} used`;
    remainingLabel = "∞";
    if (current === 0) {
      currentWidth = 0;
      remainingWidth = 100;
    } else {
      currentWidth = 20;
      remainingWidth = 80;
    }
  } else {
    progressTooltip = `${current} out of ${maxAllowed} used`;
    remainingLabel = maxAllowed - current;
    currentWidth = (current / maxAllowed) * 100;
    remainingWidth = (Number(remainingLabel) / maxAllowed) * 100;

    if (remainingLabel < 0) {
      remainingLabel = 0;
      remainingWidth = 0;
      usedVariant = "danger";
    }
  }

  return (
    <div className="row align-items-center g-0 mt-4">
      <div className="col-4">
        <span>{description.display_name}</span>
        <a
          className="lh-1 ms-3"
          style={{ paddingTop: "1px" }}
          data-bs-toggle="tooltip"
          data-bs-placement="right"
          title={description.description}
        >
          <InfoCircledIcon />
        </a>
      </div>
      <Progress.Root
        className="FlavorProgressRoot col ms-2 fw-bold"
        value={current}
        max={maxAllowed === -1 ? undefined : maxAllowed}
        data-bs-toggle="tooltip"
        data-bs-placement="top"
        title={progressTooltip}
      >
        <Progress.Indicator asChild>
          <div
            className="FlavorProgressSegment"
            data-variant={usedVariant}
            style={{ width: `${currentWidth}%` }}
          >
            {current}
          </div>
        </Progress.Indicator>
        <div
          className="FlavorProgressSegment"
          data-variant="success"
          style={{ width: `${remainingWidth}%` }}
        >
          {remainingLabel}
        </div>
      </Progress.Root>
    </div>
  );
};

export default FlavorBar;
