import { useState, useEffect } from "react";
import "./Logger.css";
import { useServerProgress } from "../../stores/SSEStore";
import type { ServerProgress } from "../../types/SSE";

export interface LogEntry {
  serverId: string;
  progress: ServerProgress;
}

function LogRow({ entry }: { entry: LogEntry }) {
  const html = entry.progress.html_message;
  const hasDetails = html?.includes("<details");

  if (hasDetails) {
    return (
      <div
        className={`log-row${entry.progress.failed ? " log-row--failed" : ""}`}
        dangerouslySetInnerHTML={{ __html: html }}
      />
    );
  }

  return (
    <div
      className={`log-row${entry.progress.failed ? " log-row--failed" : ""}`}
    >
      <span
        className="log-row__message"
        dangerouslySetInnerHTML={{
          __html: html ?? entry.progress.message ?? "",
        }}
      />
    </div>
  );
}

interface LoggerProps {
  configID: string;
}

export default function Logger({ configID }: LoggerProps) {
  const serverProgress = useServerProgress(configID);
  const [entries, setEntries] = useState<LogEntry[]>([]);

  useEffect(() => {
    if (!serverProgress) return;
    setEntries((prev) => [
      ...prev,
      { serverId: configID, progress: serverProgress },
    ]);
  }, [serverProgress]);

  return (
    <div className="logger">
      {entries.map((entry, i) => (
        <LogRow key={i} entry={entry} />
      ))}
    </div>
  );
}
