import LabelField from "./LabelField";
import TextInput from "./TextInput";

interface TextFieldProps {
  label: string;
  required?: boolean;
  enabled?: boolean;
  placeholder?: string;
  secret?: boolean;
  copy?: boolean;
  pattern?: string;
  warning?: string;
}

function TextField({
  label,
  required = false,
  enabled,
  placeholder,
  secret = false,
  copy = false,
  pattern,
  warning,
}: TextFieldProps) {
  return (
    <div
      style={{
        display: "flex",
        flexWrap: "wrap",
        alignItems: "flex-start",
        gap: 0,
        marginBottom: "0.25rem",
      }}
    >
      <LabelField label={label} htmlFor={label} />

      <TextInput
        label={label}
        required={required}
        enabled={enabled}
        placeholder={placeholder}
        secret={secret}
        copy={copy}
        pattern={pattern}
        warning={warning}
      />
    </div>
  );
}
export default TextField;
