export interface Incident {
  incident: string;
  health: number;
}

export interface Reservation {
  ReservationName: string;
  StartTime: string;
  EndTime: string;
  Duration: string;
  Nodes: string;
  NodeCnt: string;
  CoreCnt: string;
  Features: string;
  PartitionName: string;
  Flags: string;
  "TRES=cpu": string;
  Users: string;
  Groups: string;
  Accounts: string;
  Licenses: string;
  State: "ACTIVE" | "INACTIVE";
  BurstBuffer: string;
  MaxStartDelay: string;
}

export interface FlavorResources {
  cpu_guarantee: number;
  cpu_limit: number;
  mem_guarantee: string;
  mem_limit: string;
}

export interface FlavorCredits {
  interval: number;
  value: number;
}

export interface Flavor {
  credits: FlavorCredits;
  description: string;
  display_name: string;
  max: number;
  max_idle_time: number;
  resources: FlavorResources;
  weight: number;
  current: number;
}

export interface UserOptions {
  system: string;
}

export interface CreditEntry {
  balance: number;
  cap: number;
  refresh_text: string;
  user_options: UserOptions;
}

export interface ServerList {
  stopped: string[];
  stopping: string[];
}

export interface StatusMessage {
  usercount: Record<string, number>;
  incidents: Record<string, Incident>;
  reservations: Record<string, Reservation[]>;
  flavors: Record<string, Record<string, Flavor>>;
  servers: ServerList;
  credits: CreditEntry[];
}

export interface ServerProgress {
  failed: boolean;
  progress: number;
  message: string;
  html_message: string;
  ready?: boolean;
  url?: string;
}

export interface ProgressMessage {
  progress: Record<string, ServerProgress>;
}

export type SSEMessage = StatusMessage | ProgressMessage;

// Type guards
export function isStatusMessage(msg: SSEMessage): msg is StatusMessage {
  return "usercount" in msg;
}

export function isProgressMessage(msg: SSEMessage): msg is ProgressMessage {
  return "progress" in msg;
}
