import { create } from "zustand";
import { devtools } from "zustand/middleware";
import { StatusMessage, ProgressMessage, ServerProgress } from "../types/SSE";

export type ConnectionStatus =
  | "idle"
  | "connecting"
  | "connected"
  | "disconnected"
  | "error";

interface SSEStore {
  // Latest messages — only newest is kept
  latestStatus: StatusMessage | null;
  latestProgress: ProgressMessage | null;

  connectionStatus: ConnectionStatus;
  error: string | null;

  // Internal actions — called only by SSEService
  _setStatus: (msg: StatusMessage) => void;
  _setProgress: (msg: ProgressMessage) => void;
  _setConnectionStatus: (status: ConnectionStatus, error?: string) => void;
  _reset: () => void;
}

const initialState = {
  latestStatus: null,
  latestProgress: null,
  connectionStatus: "idle" as ConnectionStatus,
  error: null,
};

export const useSSEStore = create<SSEStore>()(
  devtools(
    (set) => ({
      ...initialState,

      _setStatus: (msg) => set({ latestStatus: msg }, false, "sse/setStatus"),

      _setProgress: (msg) =>
        set({ latestProgress: msg }, false, "sse/setProgress"),

      _setConnectionStatus: (connectionStatus, error = null) =>
        set({ connectionStatus, error }, false, "sse/setConnectionStatus"),

      _reset: () => set(initialState, false, "sse/reset"),
    }),
    { name: "SSEStore" },
  ),
);

// --- Selector hooks ---

export function useConnectionStatus() {
  return useSSEStore((s) => s.connectionStatus);
}

export function useLatestStatus() {
  return useSSEStore((s) => s.latestStatus);
}

export function useLatestProgress() {
  return useSSEStore((s) => s.latestProgress);
}

export function useIncidents() {
  return useSSEStore((s) => s.latestStatus?.incidents ?? null);
}

export function useReservations() {
  return useSSEStore((s) => s.latestStatus?.reservations ?? null);
}

export function useFlavors() {
  return useSSEStore((s) => s.latestStatus?.flavors ?? null);
}

export function useCredits() {
  return useSSEStore((s) => s.latestStatus?.credits ?? null);
}

export function useServers() {
  return useSSEStore((s) => s.latestStatus?.servers ?? null);
}

export function useServer(serverId: string) {
  return useSSEStore((s) => s.latestStatus?.servers[serverId] ?? null);
}

export function useServerProgress(serverId: string): ServerProgress | null {
  return useSSEStore((s) => s.latestProgress?.progress[serverId]) ?? null;
}

export function useServerState(
  serverId: string,
): "unknown" | "stopped" | "stopping" | "running" | "starting" | "connecting" {
  const servers = useSSEStore((s) => s.latestStatus?.servers);
  const progress = useSSEStore((s) => s.latestProgress?.progress[serverId]);

  if (servers === undefined && progress === undefined) {
    return "unknown";
  }

  const isStopped = servers?.stopped?.includes(serverId) ?? false;
  const isStopping = servers?.stopping?.includes(serverId) ?? false;
  const isStarting = (progress?.progress ?? 0) > 0;
  const isConnecting = progress?.ready ?? false;

  if (isStarting) return "starting";
  if (isStopped) return "stopped";
  if (isStopping) return "stopping";
  if (servers?.stopped?.includes(serverId) === false || (progress?.ready && progress?.progress === 100)) return "running";
  if (isConnecting) return "connecting";

  return "unknown";
}
