import { isStatusMessage, isProgressMessage } from "../types/SSE";
import { useSSEStore } from "../stores/SSEStore";

const RECONNECT_DELAY_MS = 3000;
const SSE_TIMEOUT_MS = 80_000;

class SSEService {
  private eventSource: EventSource | null = null;
  private url: string | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private watchdogTimer: ReturnType<typeof setTimeout> | null = null;
  private shouldReconnect = false;

  connect(url?: string) {
    if (this.eventSource) {
      console.warn("SSEService: already connected, call disconnect() first");
      return;
    }
    if (!url) {
      this.url = SSEService.buildUrl(
        window.jhdata.base_url,
        window.jhdata.user,
        window.jhdata.xsrf_token,
      );
    } else {
      this.url = url;
    }
    this.shouldReconnect = true;
    this._open();
  }

  disconnect() {
    this.shouldReconnect = false;
    this._clearReconnectTimer();
    this._clearWatchdog();
    this._close();
    useSSEStore.getState()._reset();
  }

  static buildUrl(baseUrl: string, user?: string, xsrfToken?: string): string {
    if (user && xsrfToken) {
      return `${baseUrl}api/sse/${user}?_xsrf=${xsrfToken}`;
    }
    return `${baseUrl}api/sse`;
  }

  private _open() {
    if (!this.url) return;

    const { _setStatus, _setProgress, _setConnectionStatus } =
      useSSEStore.getState();

    _setConnectionStatus("connecting");
    this.eventSource = new EventSource(this.url);

    this.eventSource.onopen = () => {
      _setConnectionStatus("connected");
      this._resetWatchdog();
    };

    this.eventSource.onmessage = (event: MessageEvent) => {
      this._resetWatchdog();

      try {
        const raw = JSON.parse(event.data);

        if (isStatusMessage(raw)) {
          _setStatus(raw);
        } else if (isProgressMessage(raw)) {
          _setProgress(raw);
        } else {
          console.warn("SSEService: unknown message shape", raw);
        }
      } catch (err) {
        console.error("SSEService: failed to parse message", event.data, err);
      }
    };

    this.eventSource.onerror = () => {
      this._close();
      this._clearWatchdog();
      _setConnectionStatus("disconnected", "Connection lost");

      if (this.shouldReconnect) {
        this._scheduleReconnect();
      }
    };
  }

  private _close() {
    this.eventSource?.close();
    this.eventSource = null;
  }

  private _resetWatchdog() {
    this._clearWatchdog();
    this.watchdogTimer = setTimeout(() => {
      console.warn(
        `SSEService: no updates for ${SSE_TIMEOUT_MS / 1000}s — reloading page`,
      );
      location.reload();
    }, SSE_TIMEOUT_MS);
  }

  private _clearWatchdog() {
    if (this.watchdogTimer !== null) {
      clearTimeout(this.watchdogTimer);
      this.watchdogTimer = null;
    }
  }

  private _scheduleReconnect() {
    this._clearReconnectTimer();
    this.reconnectTimer = setTimeout(() => {
      if (this.shouldReconnect) {
        this._open();
      }
    }, RECONNECT_DELAY_MS);
  }

  private _clearReconnectTimer() {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

export const sseService = new SSEService();
