import type { FormType } from "@/components/form/shared";
import { kubeFlavorSystems } from "@/utils/kubeHelper";

type EnvVariablesPayload = Record<string, string>;

export type CorePayload = Pick<
  FormType,
  "name" | "option" | "profile" | "system" | "flavor" | "secret_keys"
> & {
  envvariables?: EnvVariablesPayload;
};

function collectCore(form: FormType): CorePayload {
  const core: CorePayload = {
    name: form.name,
    option: form.option,
    profile: form.profile,
    system: form.system,
    flavor: form.flavor,
    secret_keys: form.secret_keys,
  };

  if (form.envvariables && form.envvariables.length > 0) {
    core.envvariables = form.envvariables.reduce<EnvVariablesPayload>(
      (acc, { name, value }) => {
        acc[name] = value;
        return acc;
      },
      {},
    );
  }

  return core;
}

type Storage = FormType["storage"];
type Resources = NonNullable<FormType["resources"]>;
type Modules = NonNullable<FormType["modules"]>;
type ModulesVersions = NonNullable<FormType["modules_versions"]>;
type Hpc = NonNullable<FormType["hpc"]>;
type Custom = NonNullable<FormType["custom"]>;
type Repo2Docker = NonNullable<FormType["repo2docker"]>;

export interface CloudPayload extends CorePayload {
  storage?: Partial<Storage>;
  modules: Modules;
  modules_versions: ModulesVersions;
  service: string;
}

export interface HpcPayload extends CorePayload {
  hpc: Hpc;
  storage?: Partial<Storage>;
  resources: Resources;
  modules: Modules;
  modules_versions: ModulesVersions;
  service: string;
}

export interface Repo2DockerPayload extends CorePayload {
  repo2docker: Repo2Docker;
  repo2dockerdirectlink: FormType["repo2dockerdirectlink"];
  storage?: Partial<Storage>;
  service: string;
}

export interface CustomPayload extends CorePayload {
  custom: Custom;
  storage?: Partial<Storage>;
  service: string;
}

export type CollectionPayload =
  | CloudPayload
  | HpcPayload
  | Repo2DockerPayload
  | CustomPayload;

export type CollectionType = "cloud" | "hpc" | "repo2docker" | "custom";

const collectionTypes = [
  "cloud",
  "hpc",
  "repo2docker",
  "custom",
] as const satisfies readonly CollectionType[];

export function isCollectionType(value: string): value is CollectionType {
  return collectionTypes.includes(value as CollectionType);
}

const collectionTypeAliases: Record<string, CollectionType> = {
  "4.2": "cloud",
  "4.3": "cloud",
  "3.6": "cloud",
};

export function resolveCollectionType(
  value: string,
): CollectionType | undefined {
  if (isCollectionType(value)) {
    return value;
  }

  return collectionTypeAliases[value];
}

export function resolveCollectionTypeFromForm(
  option: string,
  system: string,
): CollectionType | undefined {
  if (option === "custom") {
    return "custom";
  }

  if (option === "repo2docker") {
    return "repo2docker";
  }

  if (option === "xpra") {
    return "hpc";
  }
  if (kubeFlavorSystems.includes(system.trim())) {
    return "cloud";
  } else {
    return "hpc";
  }
}

function required<T>(value: T | undefined, field: string): T {
  if (value === undefined || value === null) {
    throw new Error(
      `collectionStrategy: missing required subform "${field}" for selected strategy.`,
    );
  }
  return value;
}

function cleanStorage(
  storage: Storage | undefined,
): Partial<Storage> | undefined {
  if (!storage) return undefined;

  const result: Partial<Storage> = {
    mounts: storage.mounts,
  };

  const isDefaultPath =
    storage.localstoragepath === "/home/jovyan/work" ||
    storage.localstoragepath === "";

  if (!isDefaultPath) {
    result.localstoragepath = storage.localstoragepath;
  }

  return result;
}

function isStorageEmpty(storage: Storage | undefined): boolean {
  if (!storage) return true;
  const hasNoMounts = !storage.mounts || storage.mounts.length === 0;
  const isDefaultPath =
    storage.localstoragepath === "/home/jovyan/work" ||
    storage.localstoragepath === "";
  return hasNoMounts && isDefaultPath;
}

interface CollectionStrategy<P extends CollectionPayload> {
  readonly type: CollectionType;
  collect(form: FormType): P;
}

const cloudStrategy: CollectionStrategy<CloudPayload> = {
  type: "cloud",
  collect(form) {
    const payload: CloudPayload = {
      ...collectCore(form),
      modules: required(form.modules, "modules"),
      modules_versions: required(form.modules_versions, "modules_versions"),
      service: "jupyterlab",
    };

    if (!isStorageEmpty(form.storage)) {
      payload.storage = cleanStorage(form.storage);
    }

    return payload;
  },
};

const hpcStrategy: CollectionStrategy<HpcPayload> = {
  type: "hpc",
  collect(form) {
    const payload: HpcPayload = {
      ...collectCore(form),
      hpc: required(form.hpc, "hpc"),
      resources: required(form.resources, "resources"),
      modules: required(form.modules, "modules"),
      modules_versions: required(form.modules_versions, "modules_versions"),
      service: "jupyterlab",
    };

    if (!isStorageEmpty(form.storage)) {
      payload.storage = cleanStorage(form.storage);
    }

    return payload;
  },
};

const repo2dockerStrategy: CollectionStrategy<Repo2DockerPayload> = {
  type: "repo2docker",
  collect(form) {
    const payload: Repo2DockerPayload = {
      ...collectCore(form),
      repo2docker: required(form.repo2docker, "repo2docker"),
      repo2dockerdirectlink: form.repo2dockerdirectlink,
      service: "jupyterlab",
    };

    if (!isStorageEmpty(form.storage)) {
      payload.storage = cleanStorage(form.storage);
    }

    return payload;
  },
};

const customStrategy: CollectionStrategy<CustomPayload> = {
  type: "custom",
  collect(form) {
    const payload: CustomPayload = {
      ...collectCore(form),
      custom: required(form.custom, "custom"),
      service: "jupyterlab",
    };

    if (!isStorageEmpty(form.storage)) {
      payload.storage = cleanStorage(form.storage);
    }

    return payload;
  },
};

type StrategyMap = {
  cloud: CollectionStrategy<CloudPayload>;
  hpc: CollectionStrategy<HpcPayload>;
  repo2docker: CollectionStrategy<Repo2DockerPayload>;
  custom: CollectionStrategy<CustomPayload>;
};

const strategies: StrategyMap = {
  cloud: cloudStrategy,
  hpc: hpcStrategy,
  repo2docker: repo2dockerStrategy,
  custom: customStrategy,
};

export function collect<T extends CollectionType>(
  type: T,
  form: FormType,
): Extract<CollectionPayload, { type: T }> {
  const strategy = strategies[type] as CollectionStrategy<
    Extract<CollectionPayload, { type: T }>
  >;
  return strategy.collect(form);
}
