import { useMemo } from "react";

import { useApi } from "@/hooks/useApi";

type ApiRequest = <T = unknown>(
  url: string,
  options?: RequestInit & {
    parseAs?: "json" | "text" | "blob" | "raw";
  },
) => Promise<T | null>;

type ServerRequestOptions = Omit<RequestInit, "body" | "method">;

type ServerResponse = Response;

export type StartServerPayload = unknown;
export type StartNamedServerPayload = unknown;
export type UpdateNamedServerPayload = unknown;
export type CancelNamedServerPayload = {
  failed: true;
  progress: 100;
};
export type CancelServerPayload = {
  failed: true;
  progress: 100;
  html_message: string;
};
export type DeleteNamedServerPayload = {
  remove: true;
};
export type EmptyJsonPayload = Record<string, never>;

export interface ServerService {
  startServer(
    user: string,
    payload?: StartServerPayload,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  startNamedServer(
    user: string,
    serverName: string,
    payload?: StartNamedServerPayload,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  updateNamedServer(
    user: string,
    serverName: string,
    payload: UpdateNamedServerPayload,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  cancelNamedServer(
    user: string,
    serverName: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  cancelServer(
    user: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  stopServer(
    user: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  stopNamedServer(
    user: string,
    serverName: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  deleteServer(
    user: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  deleteNamedServer(
    user: string,
    serverName: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  shareServer(options?: ServerRequestOptions): Promise<ServerResponse | null>;
  rtcNamedServerCreate(
    user: string,
    serverName: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
  rtcNamedServerRemove(
    user: string,
    serverName: string,
    options?: ServerRequestOptions,
  ): Promise<ServerResponse | null>;
}

function normalizePathSegment(segment: string) {
  return encodeURIComponent(segment);
}

function buildApiUrl(...segments: string[]) {
  const baseUrl = window.jhdata.base_url ?? "/";
  const path = segments.map(normalizePathSegment).join("/");
  const url = new URL(`${baseUrl}api/${path}`, window.location.origin);

  if (window.jhdata.xsrf_token) {
    url.searchParams.set("_xsrf", window.jhdata.xsrf_token);
  }

  return url.toString();
}

function buildJsonRequestOptions(
  method: string,
  body?: unknown,
  options: ServerRequestOptions = {},
): RequestInit & { parseAs: "raw" } {
  const requestOptions: RequestInit & { parseAs: "raw" } = {
    ...options,
    method,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...(options.headers ?? {}),
    },
    parseAs: "raw",
  };

  if (body !== undefined) {
    requestOptions.body = JSON.stringify(body);
  }

  return requestOptions;
}

export function createServerService(request: ApiRequest): ServerService {
  const post = (
    path: string[],
    body?: unknown,
    options?: ServerRequestOptions,
  ) =>
    request<ServerResponse>(
      buildApiUrl(...path),
      buildJsonRequestOptions("POST", body, options),
    );

  const del = (
    path: string[],
    body?: unknown,
    options?: ServerRequestOptions,
  ) =>
    request<ServerResponse>(
      buildApiUrl(...path),
      buildJsonRequestOptions("DELETE", body, options),
    );

  return {
    startServer(user, payload, options) {
      return post(["users", user, "server"], payload, options);
    },
    startNamedServer(user, serverName, payload, options) {
      return post(
        ["users", user, "encryptedservers", serverName],
        payload,
        options,
      );
    },
    updateNamedServer(user, serverName, payload, options) {
      return post(
        ["users", user, "servers", serverName, "update"],
        payload,
        options,
      );
    },
    cancelNamedServer(user, serverName, options) {
      return post(
        ["users", "progress", "events", user, serverName],
        { failed: true, progress: 100 } satisfies CancelNamedServerPayload,
        options,
      );
    },
    cancelServer(user, options) {
      return post(
        ["users", "progress", "events", user],
        {
          failed: true,
          progress: 100,
          html_message:
            "<details><summary>Start cancelled.</summary></details>",
        } satisfies CancelServerPayload,
        options,
      );
    },
    stopServer(user, options) {
      return del(["users", user, "server"], undefined, options);
    },
    stopNamedServer(user, serverName, options) {
      return del(["users", user, "servers", serverName], undefined, options);
    },
    deleteServer(user, options) {
      return del(["users", user, "server"], undefined, options);
    },
    deleteNamedServer(user, serverName, options) {
      return del(
        ["users", user, "servers", serverName],
        { remove: true } satisfies DeleteNamedServerPayload,
        options,
      );
    },
    shareServer(options) {
      return post(["share", "user_options"], undefined, options);
    },
    rtcNamedServerCreate(user, serverName, options) {
      return post(
        ["share-codes", user, serverName],
        {} satisfies EmptyJsonPayload,
        options,
      );
    },
    rtcNamedServerRemove(user, serverName, options) {
      return del(
        ["share-codes", user, serverName],
        {} satisfies EmptyJsonPayload,
        options,
      );
    },
  };
}

export function useServerService(): ServerService {
  const { request } = useApi();
  return useMemo(() => createServerService(request), [request]);
}
