import React, { useState } from "react";
import { Collapsible } from "radix-ui";
import JupyterLabTab from "./JupyterLabTab";
import { formSchema } from "./form/shared";
import { useAppForm, SubmitAction } from "@/hooks/formContext";
import { buildHumanReadableQuery } from "@/utils/APIUtils";
import { useStore } from "@tanstack/react-form";
import { getTransformedUserOption } from "@/utils/frontendCollectionHelper";
import { kubeSystems } from "@/utils/kubeHelper";
import { ChevronDownIcon, PlusIcon } from "@radix-ui/react-icons";
import { SummaryRowCells } from "./SummaryRowCells";
import { ProgressBar } from "./ProgressBar/ProgressBar";
import { useServerState } from "@/stores/SSEStore";
import { TabContext } from "@/hooks/TabContext";
import { getFrontendConfig } from "@/utils/frontendConfigHelper";
import { RowContext } from "@/hooks/RowContext";

const defaultSubmitAction: SubmitAction = { submitAction: null };

interface JupyterlabCollapsibleRowProps {
  configId: string;
  isFirst?: boolean;
}

const getOptionType = (
  option: string,
  system: string,
): "custom" | "repo2docker" | "hpc" | "cloud" => {
  if (option === "custom") return "custom";
  if (option === "repo2docker") return "repo2docker";
  if (kubeSystems.includes(system)) return "cloud";
  return "hpc";
};

const JupyterlabCollapsibleRow = ({
  configId,
  isFirst = false,
}: JupyterlabCollapsibleRowProps) => {
  const serverState = useServerState(configId);
  const userOption = getTransformedUserOption(configId);
  const parsed = formSchema.parse(userOption);
  const frontendConfig = getFrontendConfig();
  const [activeTab, setActiveTab] = useState(
    frontendConfig.services.options[frontendConfig.services.default].default
      .tab,
  );
  const [isRowOpen, setIsRowOpen] = useState(false);

  const form = useAppForm({
    defaultValues: parsed,
    onSubmitMeta: defaultSubmitAction,
    onSubmit: ({ value, meta }) => {
      switch (meta.submitAction) {
        case "url":
          console.log("Generated URL Query: ", buildHumanReadableQuery(value));
          break;
        case "reset":
          form.reset();
          break;
        case "submit":
          console.log("Form submitted with values: ", value);
          break;
        default:
          break;
      }
    },
    validators: {
      onChange: formSchema,
    },
  });
  const name = useStore(form.store, (state) => state.values.name);
  const system = useStore(form.store, (state) => state.values.system);
  const option = useStore(form.store, (state) => state.values.option);
  const repoType = useStore(
    form.store,
    (state) => state.values.repo2docker?.repotype,
  );
  const repoUrl = useStore(
    form.store,
    (state) => state.values.repo2docker?.repourl,
  );
  const project = useStore(form.store, (state) => state.values.hpc?.project);
  const partition = useStore(
    form.store,
    (state) => state.values.hpc?.partition,
  );
  const optionType = getOptionType(option, system);

  return (
    <RowContext.Provider
      value={{
        isRowOpen,
        openRow: () => setIsRowOpen(true),
        closeRow: () => setIsRowOpen(false),
      }}
    >
      <Collapsible.Root asChild open={isRowOpen} onOpenChange={setIsRowOpen}>
        <tbody className="jh-table__body">
          <TabContext.Provider value={{ setActiveTab }}>
            <Collapsible.Trigger asChild>
              <tr className="jh-row">
                <td>
                  {isFirst ? (
                    <PlusIcon className="jh-chevron" />
                  ) : (
                    <ChevronDownIcon className="jh-chevron" />
                  )}
                </td>
                {isFirst && <td colSpan={7}>new jupyterlab</td>}
                {!isFirst && (
                  <>
                    <td>{name}</td>
                    <SummaryRowCells
                      optionType={optionType}
                      system={system}
                      option={option}
                      repoType={repoType}
                      repoUrl={repoUrl}
                      project={project}
                      partition={partition}
                    />
                    {serverState == "unknown" && <td colSpan={2} />}
                    {serverState != "unknown" && (
                      <>
                        <td>
                          <ProgressBar serverId={configId} />
                        </td>
                        <td>
                          {serverState === "stopped" && (
                            <form.AppForm>
                              <form.start configId={configId} />
                            </form.AppForm>
                          )}
                          {serverState === "stopping" && (
                            <form.AppForm>
                              <form.cancel configId={configId} />
                            </form.AppForm>
                          )}
                          {serverState === "starting" && (
                            <form.AppForm>
                              <form.cancel configId={configId} />
                            </form.AppForm>
                          )}
                          {serverState === "connecting" && (
                            <span className="jh-server-status jh-server-status--connecting">
                              connecting
                            </span>
                          )}
                          {serverState === "running" && (
                            <>
                              <form.AppForm>
                                <form.open configId={configId} />
                              </form.AppForm>
                              <form.AppForm>
                                <form.stop configId={configId} />
                              </form.AppForm>
                            </>
                          )}
                        </td>
                      </>
                    )}
                  </>
                )}
              </tr>
            </Collapsible.Trigger>
            <Collapsible.Content asChild>
              <tr>
                <td colSpan={8} className="jh-content-cell">
                  <JupyterLabTab
                    activeTab={activeTab}
                    onTabChange={setActiveTab}
                    form={form}
                    configId={configId}
                  />
                </td>
              </tr>
            </Collapsible.Content>
          </TabContext.Provider>
        </tbody>
      </Collapsible.Root>
    </RowContext.Provider>
  );
};

export default JupyterlabCollapsibleRow;
