import { useServerService } from "@/api/ServerService";
import Button from "@/components/Button/Button";
import { useFormContext } from "@/hooks/formContext";
import { getAuthState } from "@/utils/authStateHelper";

export function CancelButton({ configId }: { configId: string }) {
  const form = useFormContext();
  const serverService = useServerService();

  const handleCancelServer = async () => {
    const user = getAuthState().name;

    try {
      const response = await serverService.cancelNamedServer(user, configId);
      if (!response) {
        console.error("Server cancel request failed");
      }
    } catch (error) {
      console.error("Failed to cancel server:", error);
    }
  };

  return (
    <form.Subscribe selector={(state) => state.isSubmitting}>
      {(isSubmitting) => (
        <Button
          type="submit"
          color="danger"
          disabled={isSubmitting}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            void handleCancelServer();
          }}
        >
          Cancel
        </Button>
      )}
    </form.Subscribe>
  );
}
