import { withForm } from "@/hooks/formContext";
import { PlusIcon, TrashIcon } from "@radix-ui/react-icons";
import "../../../style/table.css";
import "../envForm.css";
import { defaultFormValues } from "../shared";

export const EnvVariablesForm = withForm({
  defaultValues: defaultFormValues,
  render: function Render({ form }) {
    const handleAdd = () => {
      form.pushFieldValue("envvariables", {
        name: "JUPYTER_CUSTOM_VAR_",
        value: "",
      });
    };
    return (
      <div className="env-variables-entry">
        <div className="env-variables-entry__header">
          <span className="env-variables-entry__header-text">
            Add Environment Variables
          </span>
          <button
            type="button"
            className="env-variables-entry__add-btn"
            aria-label="Add environment variable"
            onClick={handleAdd}
          >
            <PlusIcon />
          </button>
        </div>

        <form.AppField name="envvariables" mode="array">
          {(field) => (
            <>
              {field.state.value.length > 0 && (
                <table className="jh-table env-variables-entry__table">
                  <thead className="jh-thead">
                    <tr>
                      <th>Variable Name</th>
                      <th>Variable Value</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {field.state.value.map((_, i) => (
                      <tr key={i} className="jh-row">
                        <td>
                          <form.AppField name={`envvariables[${i}].name`}>
                            {(subField) => (
                              <>
                                <input
                                  value={subField.state.value}
                                  className="env-variables-entry__input"
                                  placeholder="JUPYTER_CUSTOM_VAR_..."
                                  onChange={(e) =>
                                    subField.handleChange(e.target.value)
                                  }
                                  onBlur={subField.handleBlur}
                                />
                                {subField.state.meta.errors?.length > 0 && (
                                  <span className="env-variables-entry__error">
                                    {subField.state.meta.errors
                                      .map((err) => err.message ?? err)
                                      .join(", ")}
                                  </span>
                                )}
                              </>
                            )}
                          </form.AppField>
                        </td>
                        <td>
                          <form.AppField name={`envvariables[${i}].value`}>
                            {(subField) => (
                              <input
                                value={subField.state.value}
                                className="env-variables-entry__input"
                                onChange={(e) =>
                                  subField.handleChange(e.target.value)
                                }
                              />
                            )}
                          </form.AppField>
                        </td>
                        <td>
                          <button
                            type="button"
                            className="env-variables-entry__remove-btn"
                            onClick={() => field.removeValue(i)}
                            aria-label="Remove variable"
                          >
                            <TrashIcon />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </>
          )}
        </form.AppField>
      </div>
    );
  },
});
