import * as React from "react";
import { Progress } from "radix-ui";
import { useServerProgress, useServerState } from "@/stores/SSEStore";
import "./ProgressBar.css";

interface ProgressBarProps {
  serverId: string;
}

type ServerState = ReturnType<typeof useServerState>;

const STATUS_LABELS: Record<ServerState, string> = {
  stopped: "Stopped",
  stopping: "Stopping…",
  running: "Running",
  starting: "Starting…",
  connecting: "Connecting…",
};

const STATUS_VARIANTS: Record<ServerState, "success" | "danger" | "info"> = {
  running: "success",
  connecting: "success",
  starting: "info",
  stopping: "danger",
  stopped: "info", // unused, server is stopped renders nothing
};

export function ProgressBar({ serverId }: ProgressBarProps) {
  const state = useServerState(serverId);
  const progress = useServerProgress(serverId);

  if (state === "stopped" || serverId == "") {
    return null;
  }

  const isStarting = state === "starting";
  const percent = isStarting ? (progress?.progress ?? 0) : 100;
  const ifURL = progress?.url !== undefined && progress?.url !== "";
  if (ifURL) {
    const url = new URL(progress?.url ?? "", window.origin);
    console.log(`Opening server for serverId ${serverId} with URL ${url.toString()}`);
    window.open(url, "_blank");
  }
  return (
    <div className="progress-bar">
      <Progress.Root className="ProgressRoot" value={percent}>
        <Progress.Indicator
          className="ProgressIndicator"
          data-variant={STATUS_VARIANTS[state]}
          style={{ transform: `translateX(-${100 - percent}%)` }}
        />
        {isStarting && <span className="ProgressPercent">{percent}%</span>}
      </Progress.Root>
      <span className="progress-bar__status">{STATUS_LABELS[state]}</span>
    </div>
  );
}
