import { useFormContext } from "@/hooks/formContext";
import { formSchema, type FormType } from "../shared";
import { getAuthState } from "@/utils/authStateHelper";
import { collect, resolveCollectionTypeFromForm } from "@/api/CollectStrategy";
import { useServerService } from "@/api/ServerService";
import { TriangleRightIcon } from "@radix-ui/react-icons";
import Button from "@/components/Button/Button";
import { useTabContext } from "@/hooks/TabContext";
import { useRowContext } from "@/hooks/RowContext";

function _uuidv4hex(): string {
  return [1e7, 1e3, 4e3, 8e3, 1e11]
    .join("")
    .replace(/[018]/g, (c) =>
      (
        Number(c) ^
        (crypto.getRandomValues(new Uint8Array(1))[0]! &
          (15 >> (Number(c) / 4)))
      ).toString(16),
    );
}

function _uuidWithLetterStart(): string {
  const uuid = _uuidv4hex();
  const char = Math.random()
    .toString(36)
    .match(/[a-zA-Z]/)?.[0];
  if (!char) throw new Error("Failed to generate letter");
  return char + uuid.substring(1);
}

export function StartNewButton() {
  const rowContext = useRowContext();
  const tabContext = useTabContext();
  const form = useFormContext();
  const serverService = useServerService();

  async function handleStartServer() {
    const values = form.state.values as unknown as FormType;
    const validation = formSchema.safeParse(values);

    if (!validation.success) {
      console.error("Form validation errors:", validation.error.flatten());
      return;
    }

    const user = getAuthState().name;
    const collectionType = resolveCollectionTypeFromForm(
      values.option,
      values.system,
    );

    if (!collectionType) {
      console.warn(
        `Skipping collection strategy for unsupported option "${values.option}".`,
      );
      console.log("Current form values:", values);
      return;
    }

    try {
      const payload = collect(collectionType, values);
      if (!rowContext.isRowOpen) {
        rowContext.openRow();
      }
      tabContext.setActiveTab("logs");
      const newID = _uuidWithLetterStart();
      const response = await serverService.startNamedServer(
        user,
        newID,
        payload,
      );
      if (!response) {
        console.error("Server start request failed");
      }
    } catch (error) {
      console.error("Failed to collect server payload:", error);
    }
  }

  return (
    <form.Subscribe selector={(state) => state.isSubmitting}>
      {(isSubmitting) => (
        <Button
          type="submit"
          color="success"
          disabled={isSubmitting}
          icon={<TriangleRightIcon />}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            void handleStartServer();
          }}
        >
          start
        </Button>
      )}
    </form.Subscribe>
  );
}
