import Button from "@/components/Button/Button";
import { useFormContext } from "@/hooks/formContext";
import { getAuthState } from "@/utils/authStateHelper";

export function OpenButton({ configId }: { configId: string }) {
  const form = useFormContext();

  const handleOpenServer = async () => {
    const user = getAuthState().name;
    const url = new URL(
      ["user", user, configId].map(encodeURIComponent).join("/") + "/",
      window.origin,
    );
    console.log(`Opening server for user ${user} with config ${configId}`);
    console.log(`Opening URL: ${url.toString()}`);
    window.open(url, "_blank");
  };
  return (
    <form.Subscribe selector={(state) => state.isSubmitting}>
      {(isSubmitting) => (
        <Button
          type="submit"
          color="danger"
          disabled={isSubmitting}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            void handleOpenServer();
          }}
        >
          Open
        </Button>
      )}
    </form.Subscribe>
  );
}
